// ── Dijkstra's Algorithm — O((V+E) log V) ─────────────────────
// graph: adjacency list { node: [[neighbor, weight], ...] }
function dijkstra(graph, source) {
  const dist = {};
  const prev = {};
  const visited = new Set();

  for (const node of Object.keys(graph)) {
    dist[node] = Infinity;
    prev[node] = null;
  }
  dist[source] = 0;

  // Min-heap simulation with sorted array (use proper heap in production)
  const pq = [[0, source]]; // [distance, node]

  while (pq.length > 0) {
    pq.sort((a, b) => a[0] - b[0]);
    const [d, u] = pq.shift();

    if (visited.has(u)) continue;
    visited.add(u);

    for (const [v, w] of (graph[u] || [])) {
      const newDist = d + w;
      if (newDist < dist[v]) {
        dist[v] = newDist;
        prev[v] = u;
        pq.push([newDist, v]);
      }
    }
  }
  return { dist, prev };
}

// Reconstruct path from source to target
function getPath(prev, target) {
  const path = [];
  let cur = target;
  while (cur !== null) { path.unshift(cur); cur = prev[cur]; }
  return path;
}

const graph = {
  S: [["A", 4], ["B", 2]],
  A: [["T", 3]],
  B: [["A", 1], ["T", 5]],
  T: []
};

const { dist, prev } = dijkstra(graph, "S");
console.log(dist);           // { S:0, A:3, B:2, T:6 }
console.log(getPath(prev, "T"));  // ['S','B','A','T']

// ── Bellman-Ford — O(V * E), handles negative weights ─────────
// edges: array of [u, v, weight]
function bellmanFord(vertices, edges, source) {
  const dist = {};
  const prev = {};

  for (const v of vertices) {
    dist[v] = Infinity;
    prev[v] = null;
  }
  dist[source] = 0;

  // V-1 relaxation rounds
  for (let i = 0; i < vertices.length - 1; i++) {
    for (const [u, v, w] of edges) {
      if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        prev[v] = u;
      }
    }
  }

  // V-th round: detect negative cycles
  for (const [u, v, w] of edges) {
    if (dist[u] !== Infinity && dist[u] + w < dist[v]) {
      return { negativeCycle: true };
    }
  }
  return { dist, prev, negativeCycle: false };
}

// Example with a negative edge (but no negative cycle)
const vertices = ["A", "B", "C", "D"];
const edges = [
  ["A", "B",  4],
  ["A", "C",  2],
  ["B", "D",  3],
  ["C", "B", -1],  // negative edge: A→C→B costs only 1
  ["C", "D",  6]
];

const result = bellmanFord(vertices, edges, "A");
console.log(result.dist);
// { A:0, B:1, C:2, D:4 }
// Path A→C→B (cost 1) beats direct A→B (cost 4)
